/** How the one-color marks show on the island's black. */
export const MONO_MARK = "#F0F0F0";

/** Gemini CLI's rounded square in Gemini's red, violet and blue, its prompt cut into the dark face. */
export function GeminiMark({ size = 14, style, className, working }: MarkProps) {
  useLocale();
  const id = useId();
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      style={style}
      className={markClass(working, className)}
      aria-hidden
    >
      <defs>
        <linearGradient id={id} gradientUnits="userSpaceOnUse" x1="24" x2="0" y1="6.587" y2="16.494">
          <stop stopColor="#EE4D5D" />
          <stop offset=".328" stopColor="#B381DD" />
          <stop offset=".476" stopColor="#207CFE" />
        </linearGradient>
      </defs>
      <path d={GEMINI_SQUARE} fill={`url(#${id})`} />
      <path d={GEMINI_FACE} fill="#1E1E2E" fillRule="evenodd" clipRule="evenodd" />
    </svg>
  );
}

/** Google Antigravity's arch: its colored mark blurs Google's green, yellow,
 * red and blue over it, and a gradient across it keeps them in that order. */
export function AntigravityMark({ size = 14, style, className, working }: MarkProps) {
  useLocale();
  const id = useId();
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      style={style}
      className={markClass(working, className)}
      aria-hidden
    >
      <defs>
        <linearGradient id={id} gradientUnits="userSpaceOnUse" x1="0" x2="24" y1="4" y2="20">
          <stop stopColor="#00B95C" />
          <stop offset=".38" stopColor="#FFE432" />
          <stop offset=".62" stopColor="#FC413D" />
          <stop offset="1" stopColor="#3186FF" />
        </linearGradient>
      </defs>
      <path d={ANTIGRAVITY_PATH} fill={`url(#${id})`} fillRule="evenodd" />
    </svg>
  );
}

function monoMark(...parts: readonly string[]) {
  return function MonoMark({ size = 14, style, className, working }: MarkProps) {
    useLocale();
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        style={{ color: MONO_MARK, ...style }}
        className={markClass(working, className)}
        aria-hidden
      >
        {parts.map((d, i) => (
          <path key={i} d={d} fill="currentColor" fillRule="evenodd" />
        ))}
      </svg>
    );
  };
}

