function layeredMark(layers: readonly (readonly [string, string])[]) {
  return function LayeredMark({ size = 14, style, className, working }: MarkProps) {
    useLocale();
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        style={style}
        className={markClass(working, className)}
        aria-hidden
      >
        {layers.map(([d, fill]) => (
          <path key={d} d={d} fill={fill} fillRule="evenodd" />
        ))}
      </svg>
    );
  };
}

